-- Migração 33 (cw_prod): marca dos relatórios por escritório (whitelabel). Cole no SQL Editor e execute.
begin;
-- GENERATED by scripts/gen-migrations.mjs from supabase/templates. Do not edit by hand.
-- Gate 24 (D-058): whitelabel report branding per office (investment report and wealth planning report). Additive.
-- The office admin edits it; everyone in the office (staff and clients) reads it to render their reports.
create table cw_prod.report_branding (
  office_id        uuid primary key references cw_prod.offices (id) on delete cascade,
  brand_name       text not null check (length(btrim(brand_name)) between 1 and 80),
  tagline          text check (length(tagline) <= 120),
  primary_color    char(7) not null default '#0f2a44' check (primary_color ~ '^#[0-9a-f]{6}$'),
  accent_color     char(7) not null default '#b8862f' check (accent_color ~ '^#[0-9a-f]{6}$'),
  -- PNG or JPEG only (never SVG: it could carry script), as a data URL of at most ~200 KB.
  logo_data_url    text check (logo_data_url ~ '^data:image/(png|jpeg);base64,[A-Za-z0-9+/=]+$' and length(logo_data_url) <= 280000),
  invest_title     text not null default 'Relatório de Investimentos' check (length(invest_title) between 1 and 80),
  wealth_title     text not null default 'Relatório de Planejamento Patrimonial' check (length(wealth_title) between 1 and 80),
  -- Investment report layout: ordered list of visible sections.
  invest_sections  text[] not null default array['SUMMARY', 'PERFORMANCE', 'MONTHLY', 'ALLOCATION', 'STRATEGY', 'POSITIONS', 'MOVEMENTS', 'NOTES']
                   check (invest_sections <@ array['SUMMARY', 'PERFORMANCE', 'MONTHLY', 'ALLOCATION', 'STRATEGY', 'POSITIONS', 'MOVEMENTS', 'NOTES']),
  show_consultant  boolean not null default true,
  cover_note       text check (length(cover_note) <= 600),
  disclaimer       text check (length(disclaimer) <= 3000),
  contact_line     text check (length(contact_line) <= 200),
  updated_by       uuid,
  updated_at       timestamptz not null default now()
);
alter table cw_prod.report_branding enable row level security;
alter table cw_prod.report_branding force row level security;
create policy report_branding_read on cw_prod.report_branding for select to authenticated
  using (office_id = (select cw_prod_private.my_office()) or (select cw_prod_private.support_access(office_id)));
revoke all on cw_prod.report_branding from public, anon, authenticated;
grant select on cw_prod.report_branding to authenticated;
grant all on cw_prod.report_branding to service_role;
create trigger t_audit after insert or update or delete on cw_prod.report_branding for each row execute function cw_prod_private.audit_row();

create function cw_prod.report_branding_save(p_data jsonb) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if cw_prod_private.my_role() is distinct from 'ADMIN' or not cw_prod_private.staff_aal_ok() then perform cw_prod_private.deny(); end if;
  insert into cw_prod.report_branding as b (office_id, brand_name, tagline, primary_color, accent_color, logo_data_url, invest_title, wealth_title,
    invest_sections, show_consultant, cover_note, disclaimer, contact_line, updated_by)
  values (cw_prod_private.my_office(), btrim(p_data ->> 'brand_name'), nullif(btrim(p_data ->> 'tagline'), ''), lower(p_data ->> 'primary_color'), lower(p_data ->> 'accent_color'),
    nullif(p_data ->> 'logo_data_url', ''), coalesce(nullif(btrim(p_data ->> 'invest_title'), ''), 'Relatório de Investimentos'),
    coalesce(nullif(btrim(p_data ->> 'wealth_title'), ''), 'Relatório de Planejamento Patrimonial'),
    (select coalesce(array_agg(x), '{}') from jsonb_array_elements_text(coalesce(p_data -> 'invest_sections', '[]'::jsonb)) x),
    coalesce((p_data ->> 'show_consultant')::boolean, true), nullif(btrim(p_data ->> 'cover_note'), ''), nullif(btrim(p_data ->> 'disclaimer'), ''),
    nullif(btrim(p_data ->> 'contact_line'), ''), auth.uid())
  on conflict (office_id) do update set brand_name = excluded.brand_name, tagline = excluded.tagline, primary_color = excluded.primary_color,
    accent_color = excluded.accent_color,
    logo_data_url = case when p_data ? 'logo_data_url' then excluded.logo_data_url else b.logo_data_url end,
    invest_title = excluded.invest_title, wealth_title = excluded.wealth_title, invest_sections = excluded.invest_sections,
    show_consultant = excluded.show_consultant, cover_note = excluded.cover_note, disclaimer = excluded.disclaimer, contact_line = excluded.contact_line,
    updated_by = auth.uid(), updated_at = now();
end $$;
revoke all on function cw_prod.report_branding_save(jsonb) from public, anon, authenticated;
grant execute on function cw_prod.report_branding_save(jsonb) to authenticated;
commit;
select 'migração 33 ok' as resultado, to_regclass('cw_prod.report_branding') is not null as marca;
